import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"西溪易说卷二","description":"西溪易说 - 西溪易说卷二","frontmatter":{"title":"西溪易说卷二","description":"西溪易说 - 西溪易说卷二"},"headers":[],"relativePath":"zh/classics/xixi/003.md","filePath":"zh/classics/xixi/003.md"}'),i={name:"zh/classics/xixi/003.md"};function r(c,p,_,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="西溪易说卷二" tabindex="-1">西溪易说卷二 <a class="header-anchor" href="#西溪易说卷二" aria-label="Permalink to “西溪易说卷二”">​</a></h1><p>钦定四库全书</p><p>宋李过撰</p><p>䷅ 坎下乾上</p><p>「讼」：</p><p>讼：有孚，窒惕，中吉，终凶。利见大人，不利涉大川。彖曰：「讼」，</p><p>上刚下险，险而健，讼。「讼，有孚，窒惕，中吉」，刚来而得中也。「终凶」，讼不可成也。「利见大人」，尚中正也。「不利涉大川」，入于渊也。</p><p>上刚下险，险而健，讼。以健遇险，内险外健，皆所以为「讼」也。若健而不险，则不生讼；险而不健，则不能讼也。险而又健，是以「讼」也。卦辞「讼，有孚」，既「讼」矣，安得有孚哉？夫人之生，与万物同一体也。私欲固蔽，动与物敌，两不相下则成「讼」。却于私意方炽之时，天理亦自在，故曰「讼，有孚」。今人之「讼」，曲直未尝不自知也。既自知，则「有孚」矣。天理本明也，有所窒而「讼」，既讼必「惕」，「惕」，自危也。所以危者，胜负未可知也。自危而终止则吉，终其讼则凶。苟终其讼，负者固凶，而胜者亦凶。盖以讼而胜，所丧已多矣。彖，刚来而得中也。自需卦反，刚居二五，皆得中也，故能「窒惕，中吉」。讼不可成，虽胜亦凶也。「利见大人」，九五为听讼之主，天下所以中也。「不利涉大川，入于渊」也，求济其讼，其患愈深也。</p><p>象曰：天与水违行，「讼」，君子以作事谋始。</p><p>天一生水，其本同也，然其终也，天道左旋而百川东注，违行而讼之象也。君子以作事谋始：夫人之讼，皆始合而终竞，始之不谨，终必致讼，故君子必于始谋之。</p><p>初六，不永所事，小有言，终吉。象曰：「不永所事」，讼不可长也。虽「小有言」，其辩明也。</p><p>初居讼之始，以柔处下，其讼不长。方讼之始而能止也，「坎」为「小有言」，故不免讼。与四正应，四即命渝，故不成讼而终吉也。象曰：「其辩明也」，以己与四本无他，故终必辩明。</p><p>九二，不克讼，归而逋，其邑人三百户，无眚。象曰：「不克讼」，归逋窜也。自下讼上，患至掇也。</p><p>二居坎中，恃险而讼，五以臣讼君，宜不克也。君臣之分，岂有纤毫鏬隙！升降揖逊，少不如意，则明法而罪人矣，而况于讼乎！既「不克讼」，则「归而逋，其邑险」，故能奉身以窜，不可复事君也。九五中正之主，虽罪人不获，其诖误者当与自新，邑人三百户，非其眚也，所谓「纤厥渠魁，胁从罔治」是也。患至掇伤，九二之自祸。</p><p>六三，食旧德，贞厉，终吉。或从王事，无成。象曰：「食旧德」，从上吉也。</p><p>旧德，旧事也。三与上正应，本有旧事，三处险上险极，故食其旧事而讼。食，如左氏「不食其言」之「食」。然三体柔，又处危位，故能自危而守贞，是以「中吉」。夫明者争之府，三居互体杂之中，明见致争之由，在于居其成功也，故从王事而无成。惟能自克，则讼己者不期而释矣。象曰「从上吉」者，不与上讼而从三则吉也。</p><p>九四，不克讼，复即命沦，安贞吉。象曰：「复即命渝」，安贞不失也。</p><p>四与初讼而近五，九五「元吉」之主，能弭天下之讼者也，故四求决而自不成讼。「复即命渝」，自反而就命，变其始讼之意以为事，而正理依然不失也。正如虞、芮之争，至文王之境而善心油然以生，相逊而去也。曰「安贞不失」，即本然天理未尝丧。九五：讼，元吉。象曰：「讼，元吉」，以中正也。</p><p>九五处中位，以听天下之讼。然古人不贵于听讼，而贵于无讼。今也五为听讼之主，而合众议观之，初不永其讼，二不克讼，三贞厉而吉，四即命而渝，上得服而褫，皆不成讼，是天下无讼也。此九五之君所以得「元吉」也。</p><p>上九：或锡之鞶带，终朝三褫之。象曰：以讼受服，亦不足敬也。上与三讼而三逊功，故上九胜而受服。然知其不足敬也，故不待终朝而三禠之。九，健极。其始也，以刚健之资而勇于讼；其终也，以刚健之资而勇于义。惟勇于义，故不待终朝而三褫。䷆ 坎下坤上</p><p>「师」，</p><p>「师」：贞，大人吉，无咎。彖曰：「师」，众也；「贞」，正也。能以众正，可以王矣。刚中而应，行险而顺，以此毒天下，而民从之，吉又何咎矣？序卦云：「讼必有众起，故受之以师。」师之兴，必有所争也。为卦坤上坎下。以二体言之，地中有水，聚水也，为众聚之象。用兵行师，所以聚大众也。以二卦之义言之，内险外顺，险道而以顺行之，师之义也。以爻而言，一阳为众阴之主，统众之象也。比以一阳为众阴主而在上，君之象也。师以一阳为众阴主而在下，将帅之象也。卦辞：师，贞，丈人吉，无咎。贞，正也。王者之兵，直是行一不义，杀一不辜，而得天下不为。故曰：「能以众正，可以王矣。」「丈人」谓九二，以刚中之才，当主帅之任也。互体有「震」，二居「震」初，「震」为长子，丈人之象。六五为遣将之主，故又有「长子帅师，弟子舆尸」之戒。圣人之兵以顺动，然犹曰「毒天下」，见得用兵终不是好事。虽以顺动，亦不免一个「毒」字，此圣人特笔以示戒。</p><p>象曰：地中有水，「师」，君子以容民畜众。</p><p>「地中有水」，泽水也。水在泽中，则聚而不散。师所以聚众也，师败则溃也。君子观此，则当容保其民，而使众得所养。古人之兵，起于乡遂，民皆兵也，平时不恤其民，老弱转死而不顾，一日有事，则求其为上用者，难矣。</p><p>初六，师出以律，否臧凶。象曰：「师出以律」，失律凶也。初，行师之始。律，法制也。行师且当明一个法制也。汤武用兵，不免抚众，五步六步、七步，六伐、七伐，皆不可乱。周公司马法，坐作进退，皆有常节。鲁侯抚师，马牛臣妾，戒以勿逐，以其乱部分，后不可以为师也。故失律虽善亦凶。观汉李广可见。</p><p>九二，在师中，吉，无咎。王三锡命。象曰：「在师中吉」，承天宠也。「王三锡命」，怀万邦也。</p><p>坤为众，二以一阳居下卦之中，为众所主，主帅之象。古人遣将，君为之推毂，曰：「阃外之事，将军主之。」故军中之事，主帅得专也，故曰：「在师中吉。」王者之兵，不在多杀，锡命至三，谨之至也。象曰：承天宠也。师中之事，主帅得专，则众知有将而不知有君矣，必曰「承天宠也」，奉君命而行，使三军之众知命出于君也。曰「怀万邦」者，圣人用兵不得已，多杀非其心也，故三锡之意，只在绥怀。艺祖遣将，必戒以谨毋杀人。如曹彬等下诸国，未尝妄戮一人，正所谓「王三锡命，怀万邦」也。</p><p>六三，师或舆尸，凶。象曰：「师或舆尸」，大无功也。</p><p>二帅师，三以阴柔居二之上，是「舆尸」之象。舆，众也；尸，主也。任将必专，而众以主之，则自相节制，安能成功？后世用兵多败，皆缘宦者监军而节制不一之故。六四，师左次，无咎。象曰：「左次无咎」，未失常也。</p><p>六四居外卦，师已失出，量敌而后进，虑胜而后会，人命所系，不失为过谨也。上体「坤」，「坤」以顺动，故「左次无咎」。前世用兵，趋小利而败者多。</p><p>六五，田有禽，利执言，无咎。长子帅师，弟子舆尸，贞凶。象曰：「长子帅师」，以中行也；「弟子舆尸」，使不当也。</p><p>五居君位，为师之主，故言出师遣将之道。坤以顺动，奉辞伐罪之兵也，故曰「田有禽，利执言」。兵以去害，田而有禽，害民之稼，故宜猎取之。「执言」，奉辞也。后世用兵，起于私意，若秦皇、汉武，皆穷山林以索禽兽也，非「田有禽」也。任将授师之道，当以长子。长子谓二也；「弟子舆尸」，谓三也。自古任将不专而致败者，如晋荀林父邲之战、唐郭子仪之败也。</p><p>上六：大君有命，开国承家，小人勿用。象曰：「大君冇命」，以正功也。「小人勿用」，必乱邦也。</p><p>师归而赏功也。「开国」，言分封；「承家」，言袭爵。夫有功而赏，必分封袭爵以至有土，则行师之始，小人断不可用。小人有功而不赏，则非报本之意，赏则必乱邦，是去一患而生一患也。先儒只言汉韩、彭不当封，不知王者用兵，如韩、彭辈合下不用，用而有功，安得不赏？故象曰：「小人勿用，必乱邦也。」文王卦辞专言「丈人吉」，于此又有「开国承家」之戒，此义微矣，皆先儒所略。䷇ 坤下坎上</p><p>「比」，</p><p>「比」：吉。原筮，元永贞，无咎。不宁方来，后夫凶。彖曰：「比」，吉也。「比」，辅也，下顺从也。「原筮，元永贞，无咎」，以刚中也。「不宁方来」，上下应也。「后夫凶」，其道穷也。</p><p>一阳居五，五阴辅之，其卦为「比」。天下之众不能相一也，奉一人而戴之，俯首听命于其下，将以求一日之安也。曰「比吉」，比而得主则吉矣。「原」，始也。「筮」，进也。「元」，善也。「永」，久也。「贞」，正也。始进而求比，当备此三体，然后「无咎」。盖人之求「比」，当比于善，不当比于恶。当比于久，不当比于暂。当比于正，不当比于邪。比之不苟如此也。不宁方来求「比」者，以不能自相保之故也。有为之主，则同趋大安之域矣。舜巡方岳，群后毕朝。禹会涂山，玉帛万国皆来，求比宁者也。「后夫凶」，五为比主，上下皆应比，而求比不速，故宜取「凶」。六爻九五得「元永贞」之体，故彖曰「以刚中也」。五阴皆应，不宁方来也，故曰「上下应」也。「后夫凶」，谓上六也，无首，后夫也，故彖曰「其道穷也」。正如汉之田横，真人既作，而已翔海岛，将何为也？前辈谓如高帝不可事，则横将谁事？终于自绝，穷可知矣。</p><p>象曰：地上有水，「比」；先王以建万国，亲诸侯。</p><p>「地上有水」，流水也，必有所归。江汉万折，朝宗于海，天下比君之象也。圣人不自有其天下，封建万国，而使之小大相「比」，则亲诸侯乃所以亲民也。</p><p>初六，有孚比之，无咎。有孚盈缶，终来有他，吉。象曰：比之初六，「有他吉」也。</p><p>六爻皆要比五，初与五最远，四已应也。上比于五，近而得比。初未能比五，有援在四，故先比四。四居「坎」体，「坎」为「有孚」，故曰「有孚比之无咎」，言比四而得四也。五居坎中，缶之象也。初因四比五，比而相信，「有孚盈缶」也。始也比四，终焉比五，「终来冇它吉」也。正如韩信、陈平辈，因萧何、魏无知而得高帝也。</p><p>六二，比之自内，贞吉。象曰：「比之自内」，不自失也。</p><p>二居内卦之中，与五为君臣正应，不独己求五，而五亦求二，中心相应而比也。他爻以阴而外比于阳，己以正应而内相比，得比之正也，故曰「比之自内，贞吉」。象曰：「不自失也」。正道相应，由内以比，「不自失也」。汲汲而求比，非君子自重之道也，乃自失也。后世如子房事高帝，方可谓之「不自失」。</p><p>六三，比之匪人。象曰：「比之匪人」，不亦伤乎！</p><p>众皆比五，三系于上，上六无首，后夫也，而三比之，「比之匪人」也。象曰：「不亦伤乎」，深可悯也。客五百人从田横以死，其义可重也，其愚可哀也。六四，外比之，贞吉。象曰：外比于贤，以从上也。</p><p>四应在初，舍内比外，得正而吉也。九五之贤在己之上，众所同比，故象曰：「外比于贤，以从上也。」</p><p>九五，显比，王用三驱，失前禽。邑人不诫，吉。象曰：「显比」之吉，位正中也；舍逆取顺，「失前禽」也；「邑人不诫」，上使中也。以九居五，处君位，为比之主，上下皆应之。王者无私比，皇极一敷，偏陂不立，天下皆近光之民也，故曰「显比」。王者之于民，听其自归，来者不拒，往者不追也。若田猎然，礼止三驱，前禽不逐也。然圣人虽无心于晋天下，而天下自不能释然于圣人，故「攸徂之民，室家胥庆」，王师所至，玄黄以迎，有不待告语而自孚者，王者之事也，故曰「邑人不诫，吉」。象曰：「显比」之吉，位正中也。以所比者无偏陂之私也。舍逆取顺，「失前禽」也，不强天下以从之也。「邑人不诫」，上使中也；其使下也，以心感也，故不用诫。</p><p>上六：比之无首，凶。象曰：「比之无首」，无所终也。众皆比五，己独居后，后夫之「凶」也。「首」，先也；「无首」，不能为先也。象曰「无所终也」，言其身将无所措也，正如田横。䷈ 乾下巽上 「小畜」，</p><p>「小畜」：亨。密云不雨，自我西郊。彖曰：「小畜」，柔得位而上下应之，曰「小畜」。健而巽，刚中而志行，乃亨。「密云不雨」，尚往也。「自我西郊」，施未行也。</p><p>「畜」，止也。小畜、大畜，皆以止健为义。「小畜」，臣畜君也；「大畜」，君畜民也。以臣畜君，畜道之小者，以小而畜大也。上巽下健，顺而止之，畜君之道也。以阴居四，处五阳之间，五刚为一柔所畜也。四大臣位，上畜九五，而乾体在巳之下，刚健为四所止也。卦辞曰：</p><p>「小畜，亨。密云不雨，自我西郊。」臣之畜君，其畜固难；畜而亨，则畜道成矣。可以必亨者，以「柔得位而上下应之」，受畜于四，故「亨」。阴阳和则为雨，然须阳唱而阴和，则为雨可必阴唱而阳和，亦可以雨，然阳不遽和也。俗人占雨，谓「朝看东南，暮看西北」。朝属阳，故须阳；暮属阴，故须阴。东南，阳方也；西北，阴方也。今以臣畜君，阴唱也，自西郊而往也，故但密云而不成雨。然至暮而雨，则是唱者急而和者缓，喻臣畜君之难也。然终必成雨，则畜道成矣。故卦辞言「不雨」，畜未成也，上九言「既雨」，畜道成也，彖言「施未行」，未成畜也，言尚往，不以未成畜而止也。参酌而观之，然后圣人之意可见矣。</p><p>象曰：风行天上，小畜，君子以懿文德。挠万物莫疾乎风，风者，天之所以止万物者也。今不行于下而行于上，是自下止上，臣止君之象也。然风卦有形，其挠物也，吹嘘而披拂之，有柔行巽入之意。臣之畜君，全用不得刚，须雍容和缓乃告君之体，故曰「君子以懿文德」。看「文」字，又看懿字，全是柔畜之意。龙逢、比干非不忠，终非盛世事。</p><p>初九，复自道，何其咎，吉。象曰：「复自道」，其义吉也。</p><p>畜君之道，畜之于始则易，畜之于终则难。当健之初而止之，其反道也易，故曰「复自道，何其咎，吉」。象曰：「其义吉也」，正之于始，义当吉也。</p><p>九二，牵复，吉。象曰：「牵复」在中，亦不自失也。</p><p>二居健之中，畜之之道已不如初之易，须用力牵挽而复，然必进谏而纳君于善，亦畜道之美。所以能复者，以二居中故也，故象曰 云云。</p><p>九三，舆说辐，夫妻反目。象曰：「夫妻反目」，不能正室也。三而止则难矣，故必说辐毁其车而使之不得行，又不从也，则夫妻反目，君臣将不相保也。盖引裾折槛而不从，则继之以死也。象曰「不能正室」，盖不能正之于始也，至反目则末如之何矣。</p><p>六四，有孚，血去惕出，无咎。象曰：「有孚惕出」，上合志也。四以柔居大臣之位，上畜九五之刚，固难畜也，必君臣相信而后志行，故曰「有孚」。「血去惕出，有孚」，相信之深也；血，伤也，所伤既去，无说辐反目之嫌也。出，发也；惕，惧也。使其惕惧之心兢兢而发，以复于道，则君臣「无咎」矣。象曰：「上合志」，合九五之志也。</p><p>九五：有孚挛如，富以其邻。象曰：「有孚挛如」，不独富也。五冇孚，与四相从。「挛如」，固结之深，受畜于四也。阳为富，四，已之邻也。「不有其富，尚以厚其邻」，尊敬之至也，如太甲、成王之敬伊尹、周公也。象曰「不独富也」，言能谦恭待下，不有其富也。</p><p>上九：既雨既处，尚德载。妇贞厉。月几望，君子征凶。象曰：「既雨既处」，德积载也。「君子征凶」，有所疑也。「密云不雨」，畜未成也。「既雨既处」，畜道成矣。处，止也。载，成也。以六四有懿德而成畜道也。虽然，臣之于君，犹妇之于夫也，贞守此而不变则危。「月几望」，则与日敌，人臣挟畜君之功以居上位，势将敌君矣，非保身之道也，故曰「君子征凶」。于此而更征，则凶也。故太甲、成王既悔过而自悟，而伊尹、周公已有归告之志矣。象曰「有所疑」者，盖欲其「保终吉」也。䷉ 兑下乾上</p><p>履履虎尾，不咥人，亨。彖曰：「履」，柔履刚也。说而应乎乾，是以「履虎尾，不咥人，亨」。刚中正，履帝位而不疚，光明也。序卦：「物畜然后有礼，故受之以履。」「履」，礼也。天上泽下，上下之分，尊卑之等，礼之所由起也。履，行也。制行莫如礼，动容周旋皆中礼，盛德之至也。惟圣人然后可以言人伦之至。曰：「履虎尾，不咥人，亨。」虎，西方之兽也。「兑」，西方也，有虎象。虎尾在三，而五阳履之，「履虎尾」之象也。履虎尾，蹈危机也。人惟履患难而不为患难所伤，然后为履道之亨。此古人制行必以礼，喜怒哀乐有常节，尊卑贵贱有常级，饮食起居有常处，耳目手足习熟乎此，无敢过而不及也。则异时死生利害之变，卒然遇之若平时。虞舜歌南风，文王演周易，雍容暇逸，恐惧不足以累其心，此特践形之至者能之，而学者由礼以入也。平时耳目声色之娱，不足以动念，则异时死生利害之变，不足以易其所守。履虎尾而不咥，然后可以见践履之熟。狼跋之几舄，陈蔡之弦歌，至生死交变乎前，而此心不乱，其必有道矣。彖曰：履，柔履刚也。六爻一柔，履五刚也。刚不足以制天下之刚，惟柔足以制之。虎尾在三，而五爻皆刚，非履之善也，故必以柔履说而应乎乾。兑，说体也。乾，纯刚也。纯刚非履之善，须用说体以应之，然后得刚柔之中，是以「履虎尾，不咥人，亨」。故初「素履」，二「坦履」，四「诉履」，上九「视履」，皆柔履也，皆用说应乾也。刚中正，履帝位而不疚，光明也。五，君位也。君位须用刚履，然后不疚而光明。盖患难在三，初、二、四、上爻，履患难者也，当用柔履。五，君位，人君去天下之患难者也，不当言「履患难」，故五爻曰「夬履」。夬，决也，用刚一决去天下之患难也。此文王尽发。在三爻曰「眇能视，跛能履」，谓诸爻言也，即彖所谓「柔履刚，说而应乎乾」也。「武人为于大君」，谓五爻言也，即彖所谓「刚中履帝位而不疚，光明者也」。以虎尾在三，故文王于三爻发其义，夫子又就彖中详言之。学者以彖观三爻，以三爻质上下五爻，则履卦之义明矣。</p><p>象曰：上天下泽，履，君子以辨上下，定民志。</p><p>上天下泽，礼之所由起。君子辨上下，定民志，先王观象制礼以节人心，名教等级，升降揖逊，皆有常节，所以习人于死生利害之变也。民志既定，然后可以履患难。守鲁之义，弦歌如故；坏宅之变，丝竹不绝。此无他，志定故也。</p><p>初九，素履，往，无咎。象曰：「素履」之往，独行愿也。虎尾在三，而上下五刚皆履之初处下卦之下，虎尾在下体之上，人之涉世，举足皆危机也。惟能素其位而行，则各安其当然之分而不陷危机，故「素富贵行乎富贵，素贫贱行乎贫贱，素患难行乎患难」，以此而往，何咎之有！象曰：「独行愿也」，盖所愿者在我，人惟所愿乎外，故蹈危机而不自知也。</p><p>九二，履道坦坦，幽人贞吉。象曰：「幽人贞吉」，中不自乱也。虎尾在三而二近之，危机在前，非可履也，当求坦道以履，所谓脚踏实地也。当如幽人守贞则吉。二得中，故能守贞。象曰「中不自乱」，谓此。</p><p>六三，眇能视，跛能履。履虎尾，咥人，凶。武人为于大君。象曰：「眇能视」，不足以有明也；「跛能履」，不足以与行也。咥人之凶，位不当也。「武人为于大君」，志刚也。</p><p>虎尾在三，此位乃危机之所在也。凡履此者，必如眇者之视，然后谓之能视；必如跛者之履，然后谓之能履。象曰：「不足有明，不足与行。」盖眇者惟不足于明，故其视必审；跛者惟不足于行，故其动必谨。若自以为有余，则必猖狂而妄动。曰「履虎尾，咥人，凶」，此机不当，履则必为所伤。自此以上，为初、二、四上爻言也；曰「素履」、「坦履」、「诉履」、「视履」，皆致审致谨之意。「武人为于大君」，为五爻言也。大君之位当用武，不如是，不足以去天下之患难，故五曰「夬履」。夬，决也。视天下患难所在，而以刚决也。象曰：志刚也。去天下之患难，必有自强之志而后可，如汉之桓、灵，唐之敬、穆，岂足以去天下之患难？正缘虎尾在三，故为诸爻发义。</p><p>九四，履虎尾，诉诉，终吉。象曰：「诉诉终吉」，志行也。</p><p>虎尾在下而四在上，是「履虎尾」者也。「诉诉」，畏惧貌。有畏惧之志，则不至于轻举妄动，以蹈此危机也，故「终吉」。象曰：「志行也」，盖畏惧乃所以行其志也。如孟施舍之畏三军不胜，乃犹胜也；颜子之犯而不校，乃所以为大勇也。</p><p>九五，夬履，贞厉。象曰：「夬履贞厉」，位正当也。九五，君位。夬，决也。视天下患难之所在，或在权臣，或在宦官，或在女子，或在小人，或在夷狄。五，威福之权在己，一决而去之可也。区区而守贞不发，则必危，故曰「贞厉」。象曰「位正当也」。以其所居之位正当，故可以用「夬」。履：</p><p>上九：视履考祥，其旋元吉。象曰：「元吉」在上，大有庆也。上九处履之终，回视吾之所履，六爻皆得履之当，则可以「考祥」。降祥在天，不必考之于天，即视吾之所履，「永言配命，自求多福」。使吾之动容皆中礼，则为盛德之至，而天人之意可合矣，故曰「其旋元吉」。至此，履道亨矣。象曰「大有庆也」。夫祸福无门，惟人所召。古人不求福于天，而求福于己。尽易之道，则可以酬酢，可以佑神矣。夫子曰：「我祭则受福。」又曰：「吾之祷久矣。」此岂可办于临事之顷哉？其平时陟降，固与鬼神同其吉凶矣。履之有庆，当以是观。西溪易说卷二，</p>',71)])])}const m=a(i,[["render",r]]);export{h as __pageData,m as default};
